mapper.select:
SELECT * FROM notice_read
WHERE noticeid = #{noticeid}
AND studentid = #{studentid}
AND teacherid = #{teacherid}

SELECT s.studentid, s.studentname
FROM student s


        s.classid = #{classid}

    AND s.studentid NOT IN (
        SELECT studentid FROM notice_read WHERE noticeid = #{noticeid} AND studentid IS NOT NULL
    )

SELECT s.studentid, s.studentname
FROM student s
INNER JOIN homework h ON h.homeworkid = #{homeworkid}
INNER JOIN courseclass cc ON h.courseid = cc.courseid AND s.classid = cc.classid

    AND s.classid = #{classid}
    AND s.studentid NOT IN (
        SELECT studentid FROM notice_read WHERE homeworkid = #{homeworkid} AND studentid IS NOT NULL
    )

SELECT s.studentid, s.studentname, ci.classname, CASE WHEN nr.id IS NOT NULL THEN 1 ELSE 0 END as isRead, nr.readtime FROM student s INNER JOIN homework h ON h.homeworkid = #{homeworkid} INNER JOIN courseclass cc ON h.courseid = cc.courseid AND s.classid = cc.classid INNER JOIN classinfo ci ON s.classid = ci.classid LEFT JOIN notice_read nr ON nr.homeworkid = #{homeworkid} AND nr.studentid = s.studentid
AND s.classid = #{classid}
ORDER BY isRead ASC, s.studentno ASC
